ected by %d issue'=>'Big Sky er påvirket av %d problem' . "\0" . 'Big Sky er påvirket av %d problemer','Mapbox API key is set.'=>'Mapbox API-nøkkel er satt.','Mapbox API key is not set. Big Sky requires a Mapbox API key to be set.'=>'Mapbox API-nøkkel er ikke satt. Big Sky krever at en Mapbox API-nøkkel er satt.','Jetpack is connected to an admin.'=>'Jetpack er koblet til en admin.','Jetpack does not have a connected admin. Big Sky requires Jetpack to be connected to an admin.'=>'Jetpack har ikke en koblet til admin. Big Sky krever at Jetpack er koblet til en admin.','Jetpack is connected.'=>'Jetpack er koblet til.','Jetpack is not connected. Big Sky requires Jetpack to be connected.'=>'Jetpack er ikke koblet til. Big Sky krever at Jetpack er koblet til.','Jetpack is installed.'=>'Jetpack er installert.','Jetpack is not installed. Big Sky requires Jetpack to be installed and active.'=>'Jetpack er ikke installert. Big Sky krever at Jetpack er installert og aktiv.','Big Sky did not find any known issues with your site.'=>'Big Sky fant ingen kjente problemer med nettstedet ditt.','Big Sky Checks'=>'Big Sky Checks','Big Sky checks'=>'Big Sky-sjekker','AI Features'=>'AI-funksjoner','Enable AI-powered site building experience'=>'Slå på AI-drevet nettstedbyggingserfaring','Automattic, Inc.'=>'Automattic, Inc.','Big Sky'=>'Big Sky']];